#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the owner-only steps of docs/operator/DEPLOY.md, sections 1 and 2:
# create (or reuse) the release keystore, set the four OPERATOR_* repository
# secrets, back the keystore up, then tag and push a release.
#
# The password is read with hidden input and lives only in this shell's
# memory. It reaches keytool through an environment variable (-storepass:env)
# and gh through stdin, so it is never a command-line argument, never written
# to disk and never printed. Don't add `set -x` here.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
ENV_FILE=/dev/null # this wizard keeps nothing in a .env file

EXPECTED_REPO="sousadax12/Queue-Management-System"
REPO="$EXPECTED_REPO"
WORKFLOW_FILE="operator-release.yml"
SECRET_NAMES="OPERATOR_KEYSTORE_BASE64 OPERATOR_KEYSTORE_PASSWORD OPERATOR_KEY_ALIAS OPERATOR_KEY_PASSWORD"
# DEPLOY.md section 1: these must stay the same as the keytool command there.
KEYSTORE_NAME="queue-operator-release.jks"
DEFAULT_ALIAS="queue-operator"
KEY_DNAME="CN=Queue Management System operator"
DEFAULT_VERSION="2.0.0"
# The same pattern the release workflow checks the tag's version against.
VERSION_RE='^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$'

DRY_RUN=0
GH_READY=0         # gh is installed, signed in and can read the repo's secrets
KEYSTORE_PATH=""   # empty: no keystore chosen this run
KEYSTORE_CREATED=0 # 1 when this run created the keystore
KEY_ALIAS="$DEFAULT_ALIAS"
KS_PASSWORD=""
MISSING_SECRETS=""

usage() {
  cat <<EOF
Usage: scripts/operator-release-wizard.sh [--dry-run] [--help]

Walks the repository owner through docs/operator/DEPLOY.md sections 1 and 2:

  1. Preflight       keytool, gh (signed in, repo reachable), git, base64
  2. Keystore        create $KEYSTORE_NAME outside the repo, or reuse one
  3. Secrets         set the four OPERATOR_* secrets on $EXPECTED_REPO
  4. Backup          print the certificate SHA-256 and wait for your backup
  5. Tag             create and push operator-v<version> from origin/main

Run it in a terminal, on your own machine. It asks before every change and is
safe to re-run: a step that is already done (secrets set, tag pushed) is
detected and can be skipped. Stop any time with Ctrl-C.

The keystore password is typed with hidden input, is never shown, is never
written to disk and is never passed on a command line.

Options:
  --dry-run   Say what each step would do. Creates no keystore, sets no
              secret, creates no tag, and asks for no password.
  -h, --help  Show this help.

Cutover, rollback and pilot sign-off (DEPLOY.md sections 3 to 5) stay manual.
EOF
}

die()   { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }
ok()    { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
would() { printf '  %s[dry run]%s would %s\n' "$YELLOW" "$RESET" "$1"; }

# ask_default VAR "Prompt" DEFAULT: visible input; Enter takes DEFAULT.
ask_default() {
  local var="$1" prompt="$2" default="$3"
  ask "$var" "$prompt [$default]"
  [[ -n "${!var}" ]] || printf -v "$var" '%s' "$default"
}

# ask_password VAR "Prompt": ask_secret, with terminal echo already off before
# the prompt appears, so nothing typed ahead of it is ever shown.
ask_password() {
  stty -echo 2>/dev/null || true
  ask_secret "$@"
  stty echo 2>/dev/null || true
}

# expand_tilde PATH: prints PATH with a leading ~ replaced by $HOME.
expand_tilde() {
  case "$1" in
    \~)   printf '%s' "$HOME" ;;
    \~/*) printf '%s' "$HOME/${1#??}" ;;
    *)     printf '%s' "$1" ;;
  esac
}

in_git_repo() { [[ "$(git -C "$1" rev-parse --is-inside-work-tree 2>/dev/null)" == "true" ]]; }

# kt ARGS...: keytool with the password in its environment, not its arguments.
# Callers pass `-storepass:env WIZARD_STOREPASS`. English output, for parsing.
kt() { WIZARD_STOREPASS="$KS_PASSWORD" keytool -J-Duser.language=en "$@"; }

# refresh_missing_secrets: fills MISSING_SECRETS with the OPERATOR_* secrets
# the repository doesn't have (names only; values can't be read back).
refresh_missing_secrets() {
  local listed name missing=""
  listed=$(gh secret list -R "$REPO" 2>/dev/null | awk '{print $1}') || return 1
  for name in $SECRET_NAMES; do
    printf '%s\n' "$listed" | grep -qx "$name" || missing="$missing $name"
  done
  MISSING_SECRETS="${missing# }"
}

# put_secret NAME: sets the repository secret NAME from stdin.
put_secret() {
  local name="$1"
  gh secret set "$name" -R "$REPO" >/dev/null || die "couldn't set $name on $REPO (do you have admin access?)"
  WRITTEN_SECRET+=("$name")
  ok "set GitHub secret $name"
}

# keystore_base64: the keystore as one unwrapped base64 line. GNU base64
# wraps at 76 columns and BSD base64 doesn't; stripping newlines makes both
# produce the same value, which is what the Gradle build decodes.
keystore_base64() { base64 < "$KEYSTORE_PATH" | tr -d '\r\n'; }

# ── Stage 1 ───────────────────────────────────────────────────────────────

preflight() {
  local problems=0 actual origin_url

  if command -v git >/dev/null 2>&1; then ok "git"; else
    warn "git is missing. Install it: xcode-select --install (macOS) or your package manager."
    problems=$((problems + 1))
  fi
  if command -v base64 >/dev/null 2>&1; then ok "base64"; else
    warn "base64 is missing. It ships with macOS and with coreutils on Linux."
    problems=$((problems + 1))
  fi
  # macOS has a /usr/bin/keytool stub that only works once a JDK is installed.
  if command -v keytool >/dev/null 2>&1 && keytool -help >/dev/null 2>&1; then ok "keytool"; else
    warn "keytool is missing or has no Java runtime. Install a JDK: brew install --cask temurin"
    problems=$((problems + 1))
  fi
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh (GitHub CLI) is missing. Install it: brew install gh (or https://cli.github.com)"
    problems=$((problems + 1))
  elif ! gh auth status >/dev/null 2>&1; then
    warn "gh is not signed in. Run: gh auth login"
    problems=$((problems + 1))
  else
    ok "gh, signed in"
    actual=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
    if [[ -z "$actual" ]]; then
      warn "gh can't reach this checkout's GitHub repository (network? access?). Try: gh repo view"
      problems=$((problems + 1))
    else
      if [[ "$actual" == "$EXPECTED_REPO" ]]; then
        ok "repository $actual"
      else
        warn "this checkout is $actual, not $EXPECTED_REPO."
        if (( DRY_RUN )); then
          note "continuing the dry run against $actual"
        elif ! confirm "Set secrets and push the tag on $actual instead?"; then
          die "stopped: run this from a checkout of $EXPECTED_REPO"
        fi
      fi
      REPO="$actual"
      if refresh_missing_secrets; then
        GH_READY=1
        ok "can read the repository's secret names"
      else
        warn "can't list secrets on $REPO. Setting secrets needs admin access to the repository."
        problems=$((problems + 1))
      fi
    fi
  fi

  if command -v git >/dev/null 2>&1; then
    origin_url=$(git remote get-url origin 2>/dev/null || true)
    if [[ -z "$origin_url" ]]; then
      warn "this checkout has no 'origin' remote; the tag is pushed to origin."
      problems=$((problems + 1))
    elif ! printf '%s' "$origin_url" | grep -qiF "$REPO"; then
      warn "origin is $origin_url, which doesn't look like $REPO. The tag is pushed to origin."
    fi
  fi

  if (( problems )); then
    if (( DRY_RUN )); then
      warn "$problems problem(s) above: a real run would stop here."
    else
      die "fix the $problems problem(s) above, then run the wizard again"
    fi
  fi
}

# ── Stage 2 ───────────────────────────────────────────────────────────────

# read_new_password: hidden, typed twice, into KS_PASSWORD.
read_new_password() {
  local KS_PASSWORD_AGAIN=""
  say "Choose the keystore password. Use a long random one from your password manager."
  note "PKCS12 uses it for the key too, so there is only one password. Nothing is shown as you type."
  while true; do
    ask_password KS_PASSWORD "Keystore password:"
    if (( ${#KS_PASSWORD} < 6 )); then
      warn "keytool needs at least 6 characters. Try again."
      continue
    fi
    ask_password KS_PASSWORD_AGAIN "Type it again:"
    [[ "$KS_PASSWORD" == "$KS_PASSWORD_AGAIN" ]] && return 0
    warn "the two entries differ. Try again."
  done
}

# check_keystore: 0 when KS_PASSWORD opens KEYSTORE_PATH and KEY_ALIAS is a
# private key in it. Says which of the two is wrong otherwise.
check_keystore() {
  local listing
  if ! listing=$(kt -list -keystore "$KEYSTORE_PATH" -storepass:env WIZARD_STOREPASS 2>&1); then
    warn "that password doesn't open $KEYSTORE_PATH (or the file isn't a keystore)."
    return 1
  fi
  if ! printf '%s\n' "$listing" | grep -q 'Keystore type: PKCS12'; then
    warn "this keystore isn't PKCS12. The wizard uses one password for the store and the key;"
    warn "if your key has a different password, set the secrets by hand (DEPLOY.md section 1)."
  fi
  if ! listing=$(kt -list -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS" -storepass:env WIZARD_STOREPASS 2>&1); then
    warn "the password is right, but there is no alias '$KEY_ALIAS' in this keystore."
    return 2
  fi
  if ! printf '%s\n' "$listing" | grep -q 'PrivateKeyEntry'; then
    warn "alias '$KEY_ALIAS' is not a private key, so it can't sign."
    return 2
  fi
}

# reuse_keystore [PATH]: validate an existing keystore, its alias and password.
reuse_keystore() {
  local KS_FILE="${1:-}" rc
  while true; do
    if [[ -z "$KS_FILE" ]]; then
      ask_default KS_FILE "Path to your keystore file:" "$HOME/$KEYSTORE_NAME"
      KS_FILE=$(expand_tilde "$KS_FILE")
    fi
    if [[ -f "$KS_FILE" ]]; then break; fi
    warn "no file at $KS_FILE"
    KS_FILE=""
  done
  KEYSTORE_PATH="$KS_FILE"
  if in_git_repo "$(dirname "$KEYSTORE_PATH")"; then
    warn "this keystore is inside a git repository. Move it out so it can never be committed."
  fi
  while true; do
    ask_default KEY_ALIAS "Key alias:" "$DEFAULT_ALIAS"
    ask_password KS_PASSWORD "Keystore password (hidden):"
    if [[ -z "$KS_PASSWORD" ]]; then warn "the password is empty. Try again."; continue; fi
    rc=0
    check_keystore || rc=$?
    (( rc == 0 )) && break
    note "Try again, or stop with Ctrl-C."
  done
  ok "password and alias '$KEY_ALIAS' check out against $KEYSTORE_PATH"
}

create_keystore() {
  local KS_DIR="" target
  say "The keystore must live outside any git repository."
  while true; do
    ask_default KS_DIR "Folder to create $KEYSTORE_NAME in:" "$HOME"
    KS_DIR=$(expand_tilde "$KS_DIR")
    if [[ ! -d "$KS_DIR" ]]; then
      if confirm "$KS_DIR doesn't exist. Create it?"; then
        mkdir -p "$KS_DIR" || { warn "couldn't create $KS_DIR"; continue; }
      else
        continue
      fi
    fi
    KS_DIR=$(cd "$KS_DIR" && pwd -P)
    if in_git_repo "$KS_DIR"; then
      warn "$KS_DIR is inside a git repository. Pick a folder outside it."
      continue
    fi
    target="$KS_DIR/$KEYSTORE_NAME"
    if [[ -e "$target" ]]; then
      warn "$target already exists. The wizard never overwrites a keystore."
      if confirm "Use that existing keystore instead?"; then
        reuse_keystore "$target"
        return 0
      fi
      note "Pick another folder, or stop with Ctrl-C."
      continue
    fi
    break
  done

  read_new_password
  KEYSTORE_PATH="$target"
  KEY_ALIAS="$DEFAULT_ALIAS"
  say "Creating the key (RSA 4096 takes a few seconds)..."
  # umask: only you can read the file.
  if ! (umask 077 && kt -genkeypair -v -keystore "$KEYSTORE_PATH" -storetype PKCS12 \
        -alias "$KEY_ALIAS" -keyalg RSA -keysize 4096 -validity 10000 \
        -dname "$KEY_DNAME" -storepass:env WIZARD_STOREPASS >/dev/null 2>&1); then
    die "keytool couldn't create $KEYSTORE_PATH (run 'keytool -help' to check your JDK)"
  fi
  check_keystore || die "the new keystore at $KEYSTORE_PATH didn't pass its own check"
  KEYSTORE_CREATED=1
  ok "created $KEYSTORE_PATH (alias $KEY_ALIAS, RSA 4096, valid 10000 days)"
}

keystore_stage() {
  local KS_CHOICE="" default_choice=1 all_set=0
  if (( GH_READY )) && [[ -z "$MISSING_SECRETS" ]]; then all_set=1; fi

  if (( DRY_RUN )); then
    would "ask whether to create a new keystore or reuse one you have"
    would "create: ask for a folder outside any git repository and refuse to overwrite an existing file"
    would "create: read the password twice with hidden input, then run"
    note "  keytool -genkeypair -v -keystore <folder>/$KEYSTORE_NAME -storetype PKCS12 -alias $DEFAULT_ALIAS"
    note "    -keyalg RSA -keysize 4096 -validity 10000 -dname \"$KEY_DNAME\" -storepass:env <variable>"
    would "reuse: check the password and alias with keytool -list"
    if (( all_set )); then note "All four secrets are already set, so a real run offers to skip this stage."; fi
    return 0
  fi

  say "Every release is signed with one key, kept in a keystore file only you hold."
  step "1  Create a new release keystore (first time)"
  step "2  Use a keystore you already have"
  if (( all_set )); then
    step "3  Skip: the four secrets are already set on $REPO"
    default_choice=3
  fi
  while true; do
    ask_default KS_CHOICE "Your choice:" "$default_choice"
    case "$KS_CHOICE" in
      1) create_keystore; break ;;
      2) reuse_keystore; break ;;
      3) if (( all_set )); then
           note "Skipping the keystore, secrets and backup stages."
           break
         fi
         warn "Type 1 or 2." ;;
      *) warn "Type the number of one of the choices." ;;
    esac
  done
}

# ── Stage 3 ───────────────────────────────────────────────────────────────

secrets_stage() {
  local name
  if (( DRY_RUN )); then
    if (( GH_READY )); then
      if [[ -z "$MISSING_SECRETS" ]]; then
        note "All four secrets are already set on $REPO: a real run offers to skip or overwrite."
      else
        note "Not set yet on $REPO: $MISSING_SECRETS"
      fi
    fi
    would "check that the keystore survives a base64 round trip, unwrapped"
    for name in $SECRET_NAMES; do
      would "pipe the value to: gh secret set $name -R $REPO"
    done
    would "check with 'gh secret list -R $REPO' that all four exist"
    return 0
  fi

  if [[ -z "$KEYSTORE_PATH" ]]; then
    note "No keystore chosen this run: leaving the secrets as they are."
    pause
    return 0
  fi

  refresh_missing_secrets || die "couldn't list the secrets on $REPO"
  if [[ -z "$MISSING_SECRETS" ]]; then
    say "All four secrets are already set on $REPO."
    note "GitHub can't show their values, so the wizard can't tell if they match this keystore."
    if (( KEYSTORE_CREATED )); then
      warn "You just created a new keystore: the existing secrets belong to another key."
    fi
    if ! confirm "Overwrite all four from $KEYSTORE_PATH?"; then
      note "Secrets left as they are."
      pause
      return 0
    fi
  else
    say "To set on $REPO: $SECRET_NAMES"
    if ! confirm "Set them now from $KEYSTORE_PATH?"; then
      SKIPPED+=("GitHub secrets (run the wizard again, or DEPLOY.md section 1 step 3)")
      note "Secrets not set."
      pause
      return 0
    fi
  fi

  if ! keystore_base64 | base64 --decode 2>/dev/null | cmp -s - "$KEYSTORE_PATH"; then
    die "the keystore didn't survive a base64 round trip on this machine; set the secrets by hand (DEPLOY.md section 1)"
  fi
  keystore_base64            | put_secret OPERATOR_KEYSTORE_BASE64
  printf '%s' "$KS_PASSWORD" | put_secret OPERATOR_KEYSTORE_PASSWORD
  printf '%s' "$KEY_ALIAS"   | put_secret OPERATOR_KEY_ALIAS
  printf '%s' "$KS_PASSWORD" | put_secret OPERATOR_KEY_PASSWORD

  refresh_missing_secrets || die "couldn't list the secrets on $REPO to check them"
  [[ -z "$MISSING_SECRETS" ]] || die "still missing after setting: $MISSING_SECRETS"
  ok "gh secret list shows all four on $REPO"
  pause
}

# ── Stage 4 ───────────────────────────────────────────────────────────────

backup_stage() {
  local fingerprint
  if (( DRY_RUN )); then
    would "print the certificate's SHA-256 fingerprint (keytool -list -v)"
    would "wait until you confirm the keystore and its password are backed up"
    return 0
  fi
  if [[ -z "$KEYSTORE_PATH" ]]; then
    note "No keystore chosen this run, so there is no fingerprint to show."
    note "Make sure the keystore and its password are backed up (DEPLOY.md section 1 step 4)."
    pause
    return 0
  fi

  fingerprint=$(kt -list -v -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS" -storepass:env WIZARD_STOREPASS 2>/dev/null \
    | sed -n 's/^[[:space:]]*SHA256:[[:space:]]*//p' | head -n 1) || true
  [[ -n "$fingerprint" ]] || die "couldn't read the certificate fingerprint from $KEYSTORE_PATH"
  say "Signing certificate SHA-256 (not secret; every release's notes must show the same one):"
  printf '\n    %s%s%s\n\n' "$BOLD" "$fingerprint" "$RESET"

  warn "Back up now, together, somewhere that survives losing this laptop:"
  step "the keystore file: $KEYSTORE_PATH"
  step "its password, and the alias: $KEY_ALIAS"
  note "For example a password manager entry with the .jks attached, plus an offline copy."
  warn "If the keystore or its password is lost, the installed app can never be updated in place:"
  warn "every box would need an uninstall and reinstall by hand. GitHub secrets can't be read back,"
  warn "so the secret is not a backup."
  until confirm "Have you backed up the keystore file AND its password?"; do
    note "Do it now; the wizard waits. (Ctrl-C stops it; re-running is safe.)"
  done
  ok "backup confirmed"
}

# ── Stage 5 ───────────────────────────────────────────────────────────────

# find_run TAG TRIES: prints "<id> <url>" of the release run for TAG, if any.
find_run() {
  local tag="$1" tries="$2" line=""
  while (( tries > 0 )); do
    line=$(gh run list -R "$REPO" --workflow "$WORKFLOW_FILE" --branch "$tag" --event push --limit 1 \
      --json databaseId,url -q '.[0] | select(. != null) | "\(.databaseId) \(.url)"' 2>/dev/null || true)
    [[ -n "$line" ]] && break
    tries=$((tries - 1))
    (( tries > 0 )) && sleep 3
  done
  printf '%s' "$line"
}

# show_run TAG TRIES: prints the run's URL and offers to watch it.
show_run() {
  local tag="$1" tries="$2" run run_id
  run=$(find_run "$tag" "$tries")
  if [[ -z "$run" ]]; then
    say "Workflow runs: https://github.com/$REPO/actions/workflows/$WORKFLOW_FILE"
  else
    run_id="${run%% *}"
    say "Workflow run: ${run#* }"
    if confirm "Watch it here until it finishes (gh run watch)?"; then
      gh run watch "$run_id" -R "$REPO" --exit-status || warn "the run didn't succeed: open the URL above for the log"
    fi
  fi
  say "Release, once the run is green: https://github.com/$REPO/releases/tag/$tag"
  note "Its notes show the signing certificate SHA-256: it must match the one from stage 4."
}

tag_stage() {
  local RELEASE_VERSION="" tag commit on_remote

  if (( DRY_RUN )); then
    tag="operator-v$DEFAULT_VERSION"
    would "ask for the version (default $DEFAULT_VERSION, checked as <major>.<minor>.<patch>[-suffix])"
    would "run: git fetch origin main"
    would "refuse if the tag exists locally or on origin, and if a secret is missing"
    if git rev-parse -q --verify "refs/tags/$tag" >/dev/null 2>&1; then
      note "$tag exists in this checkout already."
    fi
    if on_remote=$(git ls-remote --tags origin "refs/tags/$tag" 2>/dev/null) && [[ -n "$on_remote" ]]; then
      note "$tag is already on origin: a real run would only show its workflow run."
    fi
    would "ask you to confirm, then run: git tag $tag origin/main && git push origin refs/tags/$tag"
    would "print the 'Operator release' workflow run URL and offer: gh run watch"
    return 0
  fi

  say "Pushing an operator-v* tag starts the Operator release workflow, which builds, signs"
  say "and publishes the APK as a GitHub Release."
  while true; do
    ask_default RELEASE_VERSION "Version to release:" "$DEFAULT_VERSION"
    RELEASE_VERSION="${RELEASE_VERSION#operator-v}"
    [[ "$RELEASE_VERSION" =~ $VERSION_RE ]] && break
    warn "'$RELEASE_VERSION' is not <major>.<minor>.<patch>[-suffix], e.g. 2.0.0 or 2.0.0-rc.1"
  done
  tag="operator-v$RELEASE_VERSION"

  on_remote=$(git ls-remote --tags origin "refs/tags/$tag") || die "couldn't reach origin to look for $tag"
  if [[ -n "$on_remote" ]]; then
    ok "$tag is already on origin: nothing to tag."
    show_run "$tag" 1
    return 0
  fi
  if git rev-parse -q --verify "refs/tags/$tag" >/dev/null; then
    warn "$tag exists in this checkout but not on origin. The wizard won't touch it."
    note "Push it yourself:   git push origin refs/tags/$tag"
    note "Or delete it:       git tag -d $tag    (then run the wizard again)"
    SKIPPED+=("tag $tag (exists locally, not pushed)")
    pause
    return 0
  fi

  refresh_missing_secrets || die "couldn't list the secrets on $REPO"
  if [[ -n "$MISSING_SECRETS" ]]; then
    warn "Not tagging: the release would fail, these secrets are missing: $MISSING_SECRETS"
    SKIPPED+=("tag $tag (set the secrets first, then run the wizard again)")
    pause
    return 0
  fi

  git fetch --quiet origin main || die "couldn't fetch origin/main"
  commit=$(git log -1 --format='%h %s (%cr)' origin/main)
  say "origin/main is at: $commit"
  note "Check that main is green and has what you want to ship: https://github.com/$REPO/commits/main"
  if [[ "$RELEASE_VERSION" == *-* ]]; then note "The suffix makes $tag a pre-release."; fi
  if ! confirm "Create $tag on that commit and push it? This publishes a release."; then
    SKIPPED+=("tag $tag (run the wizard again, or DEPLOY.md section 2)")
    note "No tag created."
    pause
    return 0
  fi

  git tag "$tag" origin/main || die "couldn't create $tag"
  if ! git push origin "refs/tags/$tag"; then
    git tag -d "$tag" >/dev/null 2>&1 || true
    die "couldn't push $tag (the local tag was removed, so you can run the wizard again)"
  fi
  ok "pushed $tag"
  say "Looking for the workflow run..."
  show_run "$tag" 10
  pause
}

# ── Run ───────────────────────────────────────────────────────────────────

while (( $# )); do
  case "$1" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help) usage; exit 0 ;;
    *) printf 'Unknown option: %s\n\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done

if (( ! DRY_RUN )) && [[ ! -t 0 ]]; then
  die "run this in a terminal: it asks questions and reads a password (or try --dry-run)"
fi

# Never leave the terminal with echo off, however the wizard ends.
trap 'stty echo 2>/dev/null || true' EXIT

# Work from the repository this script lives in, wherever it was started.
cd "$(dirname "$0")/.." || die "couldn't find the repository root"

if (( DRY_RUN )); then
  banner "Operator release wizard (dry run: nothing is created, set or pushed)"
else
  banner "Operator release wizard: keystore, secrets, tag"
fi

stage "Preflight"
preflight
(( DRY_RUN )) || pause

stage "Release keystore"
keystore_stage

stage "GitHub secrets"
secrets_stage

stage "Fingerprint and backup"
backup_stage

stage "Tag and release"
tag_stage

finish
if (( DRY_RUN )); then
  note "Dry run: nothing was created, set or pushed."
fi
say "Still manual, in docs/operator/DEPLOY.md:"
step "Section 3: cut a box over from Flutter"
step "Section 4: roll back to Flutter"
step "Section 5: pilot sign-off"
printf '\n'
